"use client";

import { useFramecnTheme } from "@/lib/framecn-ui";
import type { FramecnTheme } from "@/lib/framecn-ui";

export type CursorVariant = "arrow" | "pointer";

export interface CursorStyle {
  x: number;
  y: number;
  scale: number;
  rippleOpacity: number;
  rippleScale: number;
  pressScale?: number;
}

export interface CursorProps {
  style?: CursorStyle;
  variant?: CursorVariant;
  size?: number;
  theme?: Partial<FramecnTheme> | "light" | "dark";
  rippleColor?: string;
  className?: string;
}

const REST: CursorStyle = {
  rippleOpacity: 0,
  rippleScale: 0,
  scale: 1,
  x: 0,
  y: 0,
};

const ARROW_PATH =
  "M1 1 L1 18.5 L5.6 14.4 L8.7 21.6 L11.6 20.4 L8.5 13.2 L14.5 13.2 Z";
const POINTER_PATH =
  "M8 2.2 C8 1.3 8.7 0.7 9.5 0.7 C10.3 0.7 11 1.3 11 2.2 L11 9 " +
  "C11 9 11.3 8.4 12.2 8.4 C13 8.4 13.4 9 13.4 9.6 " +
  "C13.4 9.6 13.9 9.1 14.7 9.1 C15.5 9.1 15.9 9.7 15.9 10.3 " +
  "C15.9 10.3 16.4 9.9 17.1 9.9 C17.9 9.9 18.3 10.5 18.3 11.2 " +
  "L18.3 16.8 C18.3 19.8 16.3 22.3 12.8 22.3 L11.4 22.3 " +
  "C9 22.3 7.9 21.2 6.6 19.2 L4 15.2 C3.5 14.4 3.7 13.4 4.5 12.9 " +
  "C5.1 12.5 5.9 12.6 6.4 13.2 L8 15 Z";

export const Cursor = ({
  style,
  variant = "arrow",
  size = 28,
  theme: themeOverride,
  rippleColor,
  className,
}: CursorProps) => {
  const mode = typeof themeOverride === "string" ? themeOverride : undefined;
  const theme = useFramecnTheme(
    typeof themeOverride === "string" ? undefined : themeOverride,
    mode
  );
  const v = style ?? REST;
  const press = v.pressScale ?? 1;
  const pressedScale = v.scale * (0.9 + 0.1 * press);
  const ring = rippleColor ?? theme.primary;
  const fill = theme.foreground;
  const stroke = theme.background;
  const rippleSize = size * 1.8;
  return (
    <div
      className={className}
      style={{
        left: 0,
        pointerEvents: "none",
        position: "absolute",
        top: 0,
        transform: `translate(${v.x}px, ${v.y}px)`,
      }}
    >
      <div
        style={{
          border: `2px solid ${ring}`,
          borderRadius: "50%",
          height: rippleSize,
          left: -rippleSize / 2,
          opacity: v.rippleOpacity,
          position: "absolute",
          top: -rippleSize / 2,
          transform: `scale(${v.rippleScale})`,
          transformOrigin: "center",
          width: rippleSize,
        }}
      />

      <svg
        width={size}
        height={size}
        viewBox="0 0 24 24"
        fill="none"
        style={{
          filter: "drop-shadow(0 1px 2px rgba(0,0,0,0.3))",
          left: 0,
          overflow: "visible",
          position: "absolute",
          top: 0,
          transform: `scale(${pressedScale})`,
          transformOrigin: "0 0",
        }}
      >
        <path
          d={variant === "pointer" ? POINTER_PATH : ARROW_PATH}
          fill={fill}
          stroke={stroke}
          strokeWidth={1.4}
          strokeLinejoin="round"
        />
      </svg>
    </div>
  );
};

"use client";

import { clamp01, easings, useCurrentFrame } from "@/lib/framecn-ui";
import type { EasingName } from "@/lib/framecn-ui";
import type { CursorStyle } from "@/components/framecn/cursor";

export interface CursorWaypoint {
  at: number;
  x: number;
  y: number;
  duration?: number;
  click?: boolean;
  press?: boolean;
  easing?: EasingName;
}

export const DEFAULT_DURATION = 24;

export const CLICK_FRAMES = 16;

export const PRESS_FRAMES = 8;

export interface CursorPathOptions {
  speed?: number;
  defaultDuration?: number;
}

const lerp = (a: number, b: number, t: number): number => a + (b - a) * t;

const idleStyle = (x: number, y: number): CursorStyle => ({
  pressScale: 1,
  rippleOpacity: 0,
  rippleScale: 0,
  scale: 1,
  x,
  y,
});

const findToIndex = (waypoints: CursorWaypoint[], raw: number): number => {
  let toIndex = waypoints.length - 1;
  for (let i = 1; i < waypoints.length; i += 1) {
    if (waypoints[i].at > raw) {
      toIndex = i;
      break;
    }
  }
  return toIndex;
};

const lastClickAt = (waypoints: CursorWaypoint[], raw: number): number => {
  let clickAt = -Infinity;
  for (const wp of waypoints) {
    if (wp.click && wp.at <= raw && wp.at > clickAt) {
      clickAt = wp.at;
    }
  }
  return clickAt;
};

export const ripplePhase = (
  framesSinceClick: number
): {
  rippleOpacity: number;
  rippleScale: number;
} => {
  if (framesSinceClick < 0 || framesSinceClick >= CLICK_FRAMES) {
    return { rippleOpacity: 0, rippleScale: 0 };
  }
  const p = clamp01(framesSinceClick / CLICK_FRAMES);
  return {
    rippleOpacity: 0.5 * (1 - p),
    rippleScale: 2.5 * easings.out(p),
  };
};

export const clickPress = (framesSinceClick: number): number => {
  if (framesSinceClick < 0 || framesSinceClick >= PRESS_FRAMES) {
    return 1;
  }
  const half = PRESS_FRAMES / 2;
  const p =
    framesSinceClick < half
      ? framesSinceClick / half
      : 1 - (framesSinceClick - half) / half;
  return 1 - clamp01(p);
};

export const cursorPathAt = (
  waypoints: CursorWaypoint[],
  raw: number,
  opts: CursorPathOptions = {}
): CursorStyle => {
  const { defaultDuration = DEFAULT_DURATION } = opts;
  if (waypoints.length === 0) {
    return idleStyle(0, 0);
  }
  const [first] = waypoints;
  if (raw <= first.at) {
    return idleStyle(first.x, first.y);
  }

  const toIndex = findToIndex(waypoints, raw);
  const lastWp = waypoints.at(-1);
  if (!lastWp) {
    return idleStyle(0, 0);
  }

  const pastLast = raw >= lastWp.at;
  const to = pastLast ? lastWp : waypoints[toIndex];
  const from = pastLast ? lastWp : waypoints[toIndex - 1];
  if (!to || !from) {
    return idleStyle(first.x, first.y);
  }

  const dur = to.duration ?? defaultDuration;
  const ease = easings[to.easing ?? "inOut"];
  const start = to.at - dur;
  const t = pastLast || dur <= 0 ? 1 : ease(clamp01((raw - start) / dur));
  const x = lerp(from.x, to.x, t);
  const y = lerp(from.y, to.y, t);

  const clickAt = lastClickAt(waypoints, raw);
  const sinceClick = clickAt === -Infinity ? -1 : raw - clickAt;
  const ripple = ripplePhase(sinceClick);
  const clickDip = clickPress(sinceClick);
  const holdWp = pastLast ? lastWp : from;
  const heldPress = holdWp.press ? 0 : 1;
  const pressScale = Math.min(clickDip, heldPress);

  return {
    pressScale,
    rippleOpacity: ripple.rippleOpacity,
    rippleScale: ripple.rippleScale,
    scale: 1,
    x,
    y,
  };
};

export const useCursorPath = (
  waypoints: CursorWaypoint[],
  opts: CursorPathOptions = {}
): CursorStyle => {
  const { speed = 1 } = opts;
  const raw = useCurrentFrame() * speed;
  return cursorPathAt(waypoints, raw, opts);
};
